import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

const projectRoot = new URL('../../../', import.meta.url)
const read = (path) => readFileSync(new URL(path, projectRoot), 'utf8')
const registration = read('src/views/register/index.vue')
const login = read('src/views/login.vue')

function check(source, pattern, message) {
  assert.match(source, pattern, message)
}

check(registration, /class="[^"]*create-grid/, 'registration must use the prototype two-column creation grid')
check(registration, /grid-template-columns:\s*380px\s+minmax\(0,\s*1fr\)/, 'registration grid must use the prototype 380px type panel')
check(registration, /class="[^"]*rail-help/, 'continuation rail must include the prototype help card')
check(registration, /registration-copy-username/, 'credential dialog must offer individual username copy')
check(registration, /registration-copy-password/, 'credential dialog must offer individual password copy')
check(registration, /registration-toggle-credential-password/, 'credential dialog must allow password visibility toggle')
check(registration, /临时账号仅可登录并完善企业资料/, 'credential dialog must explain temporary-account restrictions')
check(login, /临时账号已生成，已自动带入/, 'login must explain that temporary credentials are prefilled')
check(login, /login-transition-overlay/, 'login must include the prototype transition overlay')
check(login, /2026/, 'login footer must match the prototype copyright year')
for (const width of ['1020px', '760px', '600px']) {
  check(`${registration}\n${login}`, new RegExp(`max-width:\\s*${width.replace('px', 'px')}`), `responsive styles must include ${width} prototype breakpoint`)
}

console.log('2334 UI contract checks passed')

